#!/usr/bin/env node
// FIST — One-shot setup script
// Run from inside your fist/ folder: node setup.js
// Creates all folders and writes all source files.
// Safe to re-run — overwrites existing files.

var fs = require('fs');
var path = require('path');

var FILES = {
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"CommonJS\",\n    \"moduleResolution\": \"node\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"declaration\": true,\n    \"declarationMap\": true,\n    \"sourceMap\": true,\n    \"outDir\": \"dist\",\n    \"rootDir\": \"src\",\n    \"composite\": true\n  },\n  \"exclude\": [\"node_modules\", \"dist\"]\n}\n",
  "packages/shared/package.json": "{\n  \"name\": \"@fist/shared\",\n  \"version\": \"0.1.0\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"^5.6.0\"\n  }\n}\n",
  "packages/shared/tsconfig.json": "{\n  \"extends\": \"../../tsconfig.json\",\n  \"compilerOptions\": {\n    \"rootDir\": \"src\",\n    \"outDir\": \"dist\"\n  },\n  \"include\": [\"src\"]\n}\n",
  "packages/shared/src/constants/game.ts": "// BOOT ORDER: First file loaded. All other packages import from here.\n// READS: Nothing \u2014 this IS the source of truth\n// DO NOT change values here without a GDD version bump\n\n// ============================================================\n// GAME CONSTANTS \u2014 from GDD v2.0.0 / Brief v3.0\n// ============================================================\n\nexport var GAME_CONSTANTS = {\n\n  // Server\n  TICK_RATE: 60,           // ticks per second\n  TICK_MS: 1000 / 60,     // ~16.67ms per tick\n\n  // Match\n  MATCH_DURATION_S: 600,   // 10 minutes Phase 1 (King of the Hill)\n  CAGE_CONTROL_RADIUS: 6,  // units \u2014 enemy within this radius interrupts hold\n  CENTER_BONUS_PER_SEC: 2, // Bling/sec while holding center\n\n  // Map\n  SAFE_NODES: 4,\n  CONTESTED_NODES: 3,\n  TOTAL_NODES: 7,\n\n  // Economy\n  BASE_YIELD: 25,          // Bling per harvest trip\n  HARVEST_TIME_S: 10.0,\n  DROP_OFF_TIME_S: 2.0,\n  ROUND_TRIP_S: 12.0,      // HARVEST_TIME_S + DROP_OFF_TIME_S\n\n  TRAINEE_START: 3,\n  TRAINEE_MAX: 10,\n  TRAINEE_COST: 50,\n  TRAINEE_TRAIN_TIME_S: 8,\n\n  // Unit costs (Bling)\n  COST_PROSPECT_TRAINING: 120,\n  COST_T1_FIGHTER: 200,\n  COST_T3_FIGHTER: 520,    // +70 from balance pass\n  COST_T5_FIGHTER: 1050,   // +150 from balance pass\n\n  // Combat\n  BASE_CRIT_CHANCE: 0.05,\n  CHAMPION_CRIT_BONUS: 0.03,\n  CRIT_SOFT_CAP: 0.20,     // diminishing returns above this\n  CRIT_MULTIPLIER: 1.75,\n  PERFECT_COUNTER_CRIT_MULT: 1.25, // Striker T3 \u2014 NOT 1.75\n\n  MAX_ACTIVE_PROCS: 2,\n  PROC_REPEAT_PENALTY: 0.70, // same proc next application = 70% of normal chance\n\n  // Cooldowns (seconds)\n  CD_PUNCH: 0.9,\n  CD_KICK: 2.2,\n  CD_GRAPPLE: 5.0,\n  CD_T1_ABILITY: 6,\n  CD_T3_ABILITY: 12,\n  CD_T5_ABILITY: 20,\n\n  // Hitstop (seconds)\n  HITSTOP_LIGHT: 0.03,\n  HITSTOP_MEDIUM: 0.06,\n  HITSTOP_HEAVY: 0.10,\n  HITSTOP_KO: 0.20,\n\n  // Camera shake intensity\n  SHAKE_NORMAL: 0.2,\n  SHAKE_HEAVY: 0.6,\n  SHAKE_KO: 1.2,\n  SLOW_MO_DURATION_S: 0.3,\n\n  // Confidence\n  CONFIDENCE_WIN_GAIN: 0.08,\n  CONFIDENCE_KO_LOSS: 0.25,\n  CONFIDENCE_PASSIVE_DECAY: 0.02, // subtracted per 10 seconds\n  CONFIDENCE_DECAY_INTERVAL_S: 10,\n\n  // Career\n  WIN_STREAK_TO_PROMOTE: 2,   // consecutive wins needed to gain a tier\n  KO_DROPS_PER_EVENT: 1,      // one KO = one tier drop, always\n\n  // Grapple\n  STRUGGLE_METER_MAX: 100,\n  CHECKMATE_ESCAPE_REDUCTION: 0.60, // Checkmate Hold reduces escape by 60%, not 100%\n\n  // Brawler chain cap (Infinite Chain upgrade)\n  BRAWLER_CHAIN_MAX: 6,\n  BRAWLER_CHAIN_DMG_PER_HIT: 0.05, // +5% per chain hit\n\n  // Technician prediction window\n  TECH_PREDICTION_INTERVAL_S: 10,\n  TECH_PREDICTION_WINDOW_S: 1.2,\n\n  // AI\n  AI_MAX_QUEUE: 3,\n  AI_QUEUE_DELAY_S: 0.1,\n  AI_ALLY_KO_CONFIDENCE_HIT: 0.15,\n  AI_REVENGE_PRIORITY_BOOST: 0.3,\n\n  // Commentary\n  COMMENTARY_COOLDOWNS_S: {\n    T1: 2,\n    T2: 4,\n    T3: 6,\n    T4: 10,\n    T5: 15,\n  },\n\n  // Limb damage\n  LIMB_BREAK_HP_PENALTY: 0.25, // flat 25% HP penalty \u2014 no animation complexity in v1\n\n} as const;\n",
  "packages/shared/src/constants/stats.ts": "// READS: nothing\n// WRITES: nothing \u2014 pure data\n\n// Post-balance pass: HP x1.1, DMG x0.9 applied\nexport var TIER_STATS = {\n  T1: { hp: 88,  baseDamage: 9,    defense: 10 },\n  T2: { hp: 121, baseDamage: 13.5, defense: 20 },\n  T3: { hp: 154, baseDamage: 19.8, defense: 35 },\n  T4: { hp: 198, baseDamage: 28.8, defense: 50 },\n  T5: { hp: 264, baseDamage: 45,   defense: 70 },\n} as const;\n\nexport var CAREER_MULTIPLIERS = {\n  TRAINEE:  { dmg: 0.6, speed: 0.70, procMin: 0.02, procMax: 0.04 },\n  PROSPECT: { dmg: 0.8, speed: 0.85, procMin: 0.05, procMax: 0.07 },\n  FIGHTER:  { dmg: 1.0, speed: 1.00, procMin: 0.08, procMax: 0.10 },\n  CHAMPION: { dmg: 1.4, speed: 1.20, procMin: 0.10, procMax: 0.15 },\n} as const;\n\n// TTK targets (seconds) \u2014 used for balance validation in test scenarios\nexport var TTK_TARGETS = {\n  T1_VS_T1: { min: 10, max: 14 },\n  T3_VS_T3: { min: 8,  max: 12 },\n  T5_VS_T5: { min: 6,  max: 9  },\n} as const;\n",
  "packages/shared/src/types/index.ts": "// BOOT ORDER: imported by all packages after constants\n// READS: nothing\n// WRITES: nothing \u2014 type definitions only\n\n// ============================================================\n// ENUMS\n// ============================================================\n\nexport enum Discipline {\n  STRIKER    = 'Striker',\n  GRAPPLER   = 'Grappler',\n  BRAWLER    = 'Brawler',\n  TECHNICIAN = 'Technician',\n  SPECIALIST = 'Specialist',\n}\n\nexport enum CareerState {\n  TRAINEE   = 'Trainee',\n  PROSPECT  = 'Prospect',\n  FIGHTER   = 'Fighter',\n  CHAMPION  = 'Champion',\n}\n\n// Career state numeric ladder \u2014 used for drop/promote logic\nexport var CAREER_LADDER: CareerState[] = [\n  CareerState.TRAINEE,\n  CareerState.PROSPECT,\n  CareerState.FIGHTER,\n  CareerState.CHAMPION,\n];\n\nexport enum AIState {\n  AGGRESSIVE    = 'Aggressive',\n  DEFENSIVE     = 'Defensive',\n  PANICKED      = 'Panicked',\n  OPPORTUNISTIC = 'Opportunistic',\n}\n\nexport enum ProcType {\n  BLEED   = 'BLEED',   // 2% HP/sec for 5s\n  STAGGER = 'STAGGER', // +1.5s cooldown delay on defender\n  RAGE    = 'RAGE',    // +25% DMG on attacker for 4s\n  DEVOLVE = 'DEVOLVE', // 10% chance to force hesitation\n}\n\nexport enum ActionType {\n  PUNCH   = 'PUNCH',\n  KICK    = 'KICK',\n  BLOCK   = 'BLOCK',\n  GRAPPLE = 'GRAPPLE',\n  ABILITY = 'ABILITY',\n  MOVE    = 'MOVE',\n  RETREAT = 'RETREAT',\n}\n\nexport enum CommentaryTier {\n  T1 = 'T1', // damage > 5% HP\n  T2 = 'T2', // chain >= 3\n  T3 = 'T3', // KO\n  T4 = 'T4', // comeback\n  T5 = 'T5', // multi-KO\n}\n\n// ============================================================\n// POSITION\n// ============================================================\n\nexport interface Vec2 {\n  x: number;\n  y: number;\n}\n\n// ============================================================\n// ENTITY\n// ============================================================\n\nexport interface Entity {\n  id: string;\n  playerId: string;          // which player owns this unit\n  discipline: Discipline;\n  tier: 1 | 2 | 3 | 4 | 5;\n  careerState: CareerState;\n  position: Vec2;\n  velocity: Vec2;\n  confidence: number;        // 0.0 \u2192 1.0 \u2014 NEVER exposed to client UI directly\n  hp: number;\n  maxHp: number;\n  baseDamage: number;\n  defense: number;\n  speed: number;\n  cooldowns: Partial<Record<ActionType | string, number>>; // remaining cooldown in seconds\n  activeProcs: ActiveProc[];\n  aiState: AIState;\n  memory: UnitMemory;\n  isTrainee: boolean;        // true = peon harvester, false = fighter\n  isHarvesting: boolean;\n  harvestTarget: string | null; // node id\n  winStreak: number;\n  koCount: number;\n  struggleMeter: number;     // 0 \u2192 100, filled by player input during grapple\n  chainCount: number;        // Brawler Infinite Chain tracker\n  isAlive: boolean;\n  hasThrownInTowel: boolean; // true = permanently removed from match\n}\n\n// ============================================================\n// PROCS\n// ============================================================\n\nexport interface ActiveProc {\n  type: ProcType;\n  remainingS: number;  // seconds left\n  value: number;       // damage, multiplier, etc. depending on type\n  sourceId: string;    // entity that applied this\n}\n\n// ============================================================\n// AI MEMORY\n// ============================================================\n\nexport interface UnitMemory {\n  lastHitById: string | null;\n  lastKOById: string | null;\n  recentMoves: ActionType[];   // last 3 moves seen from this unit's current target\n  failedAbilities: string[];\n}\n\n// ============================================================\n// COMMANDS (player \u2192 server)\n// ============================================================\n\nexport interface Command {\n  type: ActionType;\n  unitId: string;\n  targetId?: string;          // entity id for attack/grapple\n  targetPos?: Vec2;           // world position for move\n  abilityKey?: string;        // 'T1' | 'T3' | 'T5'\n  timestamp: number;          // client timestamp for lag compensation\n}\n\n// ============================================================\n// COMBAT RESULTS\n// ============================================================\n\nexport interface AttackResult {\n  hit: boolean;\n  damage: number;\n  isCrit: boolean;\n  proc: ProcType | null;\n  isKO: boolean;\n  careerDropped: boolean;     // true if KO caused a career state drop\n  traineeExited: boolean;     // true if Trainee was KO'd and threw in the towel\n}\n\n// ============================================================\n// NODES (resource + center objective)\n// ============================================================\n\nexport interface MapNode {\n  id: string;\n  position: Vec2;\n  isContested: boolean;\n  isCenter: boolean;\n  currentHolderId: string | null;   // player id\n  accumulatedHoldTime: Record<string, number>; // playerId \u2192 seconds held\n}\n\n// ============================================================\n// PLAYER\n// ============================================================\n\nexport interface Player {\n  id: string;\n  discipline: Discipline;\n  bling: number;\n  respect: number;            // team Respect \u2014 earned in combat\n  totalCenterTimeS: number;   // accumulated center hold time \u2014 win condition\n  entities: string[];         // entity ids owned by this player\n  basePosition: Vec2;\n  isConnected: boolean;\n}\n\n// ============================================================\n// GAME STATE (authoritative \u2014 lives on server)\n// ============================================================\n\nexport interface GameState {\n  tick: number;\n  matchElapsedS: number;\n  matchDurationS: number;     // 600 (10 minutes)\n  players: Record<string, Player>;\n  entities: Record<string, Entity>;\n  nodes: Record<string, MapNode>;\n  events: GameEvent[];        // flushed each tick\n  phase: 'WAR' | 'ENDED';\n  winnerId: string | null;\n}\n\n// ============================================================\n// EVENTS (all registered events \u2014 feed commentary + AI + analytics)\n// ============================================================\n\nexport type GameEventType =\n  // Combat\n  | 'limb_break'\n  | 'torso_trauma'\n  | 'reset_shockwave'\n  | 'unit_kill'\n  | 'hero_entry'\n  | 'hero_ability'\n  | 'venue_transition'\n  | 'final_descent'\n  | '1v1_standoff'\n  | 'comeback'\n  | 'humiliation'\n  | 'miss_streak'\n  | 'clutch_evade'\n  | 'bleed_out'\n  | 'last_unit_alive'\n  | 'crit_hit'\n  | 'proc_chain'\n  // Career\n  | 'career_drop'\n  | 'career_recovery'\n  | 'trainee_exit'\n  | 'confidence_collapse'\n  | 'comeback_arc'\n  | 'champion_at_risk'\n  | 'trainee_deployed'\n  // Economy\n  | 'bling_spent'\n  | 'bling_harvested'\n  | 'upgrade_purchased'\n  | 'base_expanded'\n  // Match\n  | 'cage_control_achieved'\n  | 'phase_transition'\n  | 'match_end';\n\nexport interface GameEvent {\n  type: GameEventType;\n  tick: number;\n  sourceId?: string;   // entity or player id\n  targetId?: string;\n  value?: number;      // damage, bling amount, etc.\n  data?: Record<string, unknown>;\n}\n\n// ============================================================\n// NETWORK SNAPSHOT (server \u2192 client every tick)\n// ============================================================\n\nexport interface EntitySnapshot {\n  id: string;\n  pos: Vec2;\n  hp: number;\n  maxHp: number;\n  careerState: CareerState;\n  aiState: AIState;\n  confidence: number;   // used for glow/flicker FX on client \u2014 not shown as number\n  isAlive: boolean;\n  isHarvesting: boolean;\n  activeProcs: ProcType[];\n}\n\nexport interface Snapshot {\n  tick: number;\n  matchElapsedS: number;\n  players: Record<string, {\n    bling: number;\n    respect: number;\n    totalCenterTimeS: number;\n  }>;\n  entities: EntitySnapshot[];\n  events: GameEvent[];   // events that fired this tick\n}\n",
  "packages/shared/src/index.ts": "export * from './constants/game';\nexport * from './constants/stats';\nexport * from './types/index';\n",
  "packages/engine/package.json": "{\n  \"name\": \"@fist/engine\",\n  \"version\": \"0.1.0\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  },\n  \"dependencies\": {\n    \"@fist/shared\": \"*\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"^5.6.0\"\n  }\n}\n",
  "packages/engine/tsconfig.json": "{\n  \"extends\": \"../../tsconfig.json\",\n  \"compilerOptions\": {\n    \"rootDir\": \"src\",\n    \"outDir\": \"dist\"\n  },\n  \"references\": [\n    { \"path\": \"../shared\" }\n  ],\n  \"include\": [\"src\"]\n}\n",
  "packages/engine/src/combat/resolver.ts": "// BOOT ORDER: loaded by server tick loop\n// READS: entity.hp, entity.confidence, entity.careerState, entity.cooldowns\n// WRITES: entity.hp, entity.careerState, entity.activeProcs, entity.isAlive\n\nimport {\n  Entity,\n  AttackResult,\n  ProcType,\n  CareerState,\n  CAREER_LADDER,\n  ActionType,\n  GameEvent,\n  GameEventType,\n} from '@fist/shared';\n\nimport {\n  GAME_CONSTANTS,\n  CAREER_MULTIPLIERS,\n} from '@fist/shared';\n\n// ============================================================\n// SEEDED RNG \u2014 server only, never client\n// ============================================================\n\n// DEPENDS ON: nothing \u2014 self-contained PRNG\n// Simple mulberry32 seeded RNG. Server seeds on match start.\nvar _seed = Date.now();\n\nfunction seededRandom(): number {\n  _seed |= 0;\n  _seed = (_seed + 0x6D2B79F5) | 0;\n  var t = Math.imul(_seed ^ (_seed >>> 15), 1 | _seed);\n  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n}\n\nexport function seedRNG(seed: number): void {\n  _seed = seed;\n}\n\n// ============================================================\n// DAMAGE FORMULA\n// GDD: (baseDMG \u00d7 careerMult) \u00d7 crit \u00d7 (1 - DEF / (DEF + 100))\n// ============================================================\n\n// DEPENDS ON: CAREER_MULTIPLIERS, GAME_CONSTANTS\nexport function calculateDamage(\n  attacker: Entity,\n  defender: Entity,\n  isCrit: boolean\n): number {\n  var mult = CAREER_MULTIPLIERS[attacker.careerState];\n  var base = attacker.baseDamage * mult.dmg;\n\n  var critMult = isCrit ? GAME_CONSTANTS.CRIT_MULTIPLIER : 1.0;\n\n  var mitigation = defender.defense / (defender.defense + 100);\n  var damage = base * critMult * (1 - mitigation);\n\n  return Math.max(1, Math.round(damage));\n}\n\n// ============================================================\n// CRIT CHECK\n// Soft cap: above 20% crit chance, diminishing returns apply\n// ============================================================\n\n// DEPENDS ON: GAME_CONSTANTS\nexport function rollCrit(attacker: Entity): boolean {\n  var base = GAME_CONSTANTS.BASE_CRIT_CHANCE;\n  var bonus = attacker.careerState === CareerState.CHAMPION\n    ? GAME_CONSTANTS.CHAMPION_CRIT_BONUS\n    : 0;\n\n  var raw = base + bonus;\n\n  // Soft cap \u2014 above 20%, each additional % is worth half\n  var effective: number;\n  if (raw <= GAME_CONSTANTS.CRIT_SOFT_CAP) {\n    effective = raw;\n  } else {\n    var excess = raw - GAME_CONSTANTS.CRIT_SOFT_CAP;\n    effective = GAME_CONSTANTS.CRIT_SOFT_CAP + excess * 0.5;\n  }\n\n  return seededRandom() < effective;\n}\n\n// ============================================================\n// PROC ROLL \u2014 confidence determines where in career band we land\n// ============================================================\n\n// DEPENDS ON: CAREER_MULTIPLIERS, GAME_CONSTANTS\nexport function rollProc(attacker: Entity): boolean {\n  var band = CAREER_MULTIPLIERS[attacker.careerState];\n\n  // Confidence (0\u21921) linearly interpolates within the career band\n  var procChance = band.procMin + (band.procMax - band.procMin) * attacker.confidence;\n\n  // Noise: \u00b110% variation\n  var noise = 0.9 + seededRandom() * 0.2;\n  procChance *= noise;\n\n  return seededRandom() < procChance;\n}\n\n// ============================================================\n// PROC SELECTION \u2014 weighted by active proc state\n// ============================================================\n\nvar PROC_POOL: ProcType[] = [\n  ProcType.BLEED,\n  ProcType.STAGGER,\n  ProcType.RAGE,\n  ProcType.DEVOLVE,\n];\n\n// DEPENDS ON: GAME_CONSTANTS\nexport function selectProc(attacker: Entity, defender: Entity): ProcType {\n  // Filter: if we already have max procs active on defender, don't add another\n  if (defender.activeProcs.length >= GAME_CONSTANTS.MAX_ACTIVE_PROCS) {\n    return ProcType.STAGGER; // fallback: stagger is lowest-impact\n  }\n\n  // Apply repeat penalty \u2014 same proc type gets reduced weight\n  var activeProcTypes = defender.activeProcs.map(function(p) { return p.type; });\n\n  var weights = PROC_POOL.map(function(proc) {\n    var isRepeat = activeProcTypes.includes(proc);\n    return isRepeat ? GAME_CONSTANTS.PROC_REPEAT_PENALTY : 1.0;\n  });\n\n  var total = weights.reduce(function(a, b) { return a + b; }, 0);\n  var roll = seededRandom() * total;\n  var cumulative = 0;\n\n  for (var i = 0; i < PROC_POOL.length; i++) {\n    cumulative += weights[i];\n    if (roll <= cumulative) return PROC_POOL[i];\n  }\n\n  return ProcType.BLEED;\n}\n\n// ============================================================\n// APPLY PROC to defender/attacker\n// ============================================================\n\n// READS: entity.activeProcs\n// WRITES: entity.activeProcs (push new proc)\nexport function applyProc(\n  proc: ProcType,\n  attacker: Entity,\n  defender: Entity\n): void {\n  switch (proc) {\n    case ProcType.BLEED:\n      // 2% HP/sec for 5s \u2014 applied to defender\n      defender.activeProcs.push({\n        type: ProcType.BLEED,\n        remainingS: 5,\n        value: 0.02,\n        sourceId: attacker.id,\n      });\n      break;\n\n    case ProcType.STAGGER:\n      // +1.5s added to all defender cooldowns\n      Object.keys(defender.cooldowns).forEach(function(key) {\n        var k = key as ActionType;\n        defender.cooldowns[k] = (defender.cooldowns[k] ?? 0) + 1.5;\n      });\n      break;\n\n    case ProcType.RAGE:\n      // +25% DMG on attacker for 4s \u2014 modeled as a short-lived proc\n      attacker.activeProcs.push({\n        type: ProcType.RAGE,\n        remainingS: 4,\n        value: 1.25,\n        sourceId: attacker.id,\n      });\n      break;\n\n    case ProcType.DEVOLVE:\n      // 10% chance to force hesitation \u2014 adds 2s to next action cooldown\n      if (seededRandom() < 0.10) {\n        defender.cooldowns[ActionType.PUNCH] =\n          Math.max(defender.cooldowns[ActionType.PUNCH] ?? 0, 2.0);\n      }\n      break;\n  }\n}\n\n// ============================================================\n// TICK PROCS \u2014 decrement timers, apply ongoing effects\n// ============================================================\n\n// READS: entity.activeProcs, entity.hp\n// WRITES: entity.activeProcs, entity.hp\nexport function tickProcs(entity: Entity, deltaS: number): void {\n  var toRemove: number[] = [];\n\n  entity.activeProcs.forEach(function(proc, idx) {\n    proc.remainingS -= deltaS;\n\n    if (proc.type === ProcType.BLEED) {\n      var bleedDmg = entity.maxHp * proc.value * deltaS;\n      entity.hp = Math.max(0, entity.hp - bleedDmg);\n    }\n\n    if (proc.remainingS <= 0) {\n      toRemove.push(idx);\n    }\n  });\n\n  // Remove expired procs (iterate backwards to preserve indices)\n  for (var i = toRemove.length - 1; i >= 0; i--) {\n    entity.activeProcs.splice(toRemove[i], 1);\n  }\n}\n\n// ============================================================\n// HANDLE KO \u2014 career drop, trainee exit, confidence hit\n// ============================================================\n\n// READS: entity.careerState, entity.isTrainee\n// WRITES: entity.careerState, entity.isAlive, entity.hasThrownInTowel,\n//         entity.confidence, entity.hp\nexport function handleKO(\n  defender: Entity,\n  attacker: Entity | null,\n  events: GameEvent[],\n  tick: number\n): void {\n  var currentIndex = CAREER_LADDER.indexOf(defender.careerState);\n\n  if (defender.isTrainee || defender.careerState === CareerState.TRAINEE) {\n    // Trainee KO = throw in the towel \u2014 permanently exits match\n    defender.isAlive = false;\n    defender.hasThrownInTowel = true;\n    defender.confidence = 0;\n\n    events.push({\n      type: 'trainee_exit' as GameEventType,\n      tick,\n      sourceId: defender.id,\n      targetId: attacker?.id,\n    });\n    return;\n  }\n\n  // One tier drop, always \u2014 NO instant double drop\n  var newIndex = Math.max(0, currentIndex - 1);\n  var newState = CAREER_LADDER[newIndex];\n  var dropped = newState !== defender.careerState;\n\n  defender.careerState = newState;\n  defender.confidence = Math.max(0, defender.confidence - GAME_CONSTANTS.CONFIDENCE_KO_LOSS);\n  defender.hp = Math.round(defender.maxHp * 0.5); // restore to 50% after KO\n  defender.winStreak = 0;\n  defender.koCount++;\n\n  if (dropped) {\n    events.push({\n      type: 'career_drop' as GameEventType,\n      tick,\n      sourceId: attacker?.id,\n      targetId: defender.id,\n      data: { from: CAREER_LADDER[currentIndex], to: newState },\n    });\n  }\n\n  // Check if now a Trainee \u2014 flag champion_at_risk if near exit\n  if (defender.careerState === CareerState.TRAINEE) {\n    events.push({\n      type: 'champion_at_risk' as GameEventType,\n      tick,\n      targetId: defender.id,\n    });\n  }\n}\n\n// ============================================================\n// FULL ATTACK RESOLUTION\n// Called by the server tick loop for every attack action\n// ============================================================\n\n// DEPENDS ON: calculateDamage, rollCrit, rollProc, selectProc,\n//             applyProc, handleKO\n// READS: attacker stats, defender stats\n// WRITES: defender.hp, defender.activeProcs, events[]\nexport function resolveAttack(\n  attacker: Entity,\n  defender: Entity,\n  events: GameEvent[],\n  tick: number\n): AttackResult {\n  // Miss check \u2014 trainees have higher miss rate\n  var missChance = attacker.isTrainee ? 0.20 : 0.05;\n  if (seededRandom() < missChance) {\n    return {\n      hit: false,\n      damage: 0,\n      isCrit: false,\n      proc: null,\n      isKO: false,\n      careerDropped: false,\n      traineeExited: false,\n    };\n  }\n\n  var isCrit = rollCrit(attacker);\n  var damage = calculateDamage(attacker, defender, isCrit);\n\n  // Apply RAGE proc bonus if attacker has one active\n  var rageMult = attacker.activeProcs.find(function(p) { return p.type === ProcType.RAGE; });\n  if (rageMult) {\n    damage = Math.round(damage * rageMult.value);\n  }\n\n  defender.hp = Math.max(0, defender.hp - damage);\n\n  // Proc roll\n  var procFired: ProcType | null = null;\n  if (rollProc(attacker)) {\n    procFired = selectProc(attacker, defender);\n    applyProc(procFired, attacker, defender);\n\n    events.push({\n      type: 'proc_chain' as GameEventType,\n      tick,\n      sourceId: attacker.id,\n      targetId: defender.id,\n      data: { proc: procFired },\n    });\n  }\n\n  if (isCrit) {\n    events.push({\n      type: 'crit_hit' as GameEventType,\n      tick,\n      sourceId: attacker.id,\n      targetId: defender.id,\n      value: damage,\n    });\n  }\n\n  // Confidence feedback\n  attacker.confidence = Math.min(1, attacker.confidence + GAME_CONSTANTS.CONFIDENCE_WIN_GAIN);\n  defender.confidence = Math.max(0, defender.confidence - 0.04);\n\n  // KO check\n  var isKO = defender.hp <= 0;\n  var careerDropped = false;\n  var traineeExited = false;\n\n  if (isKO) {\n    var prevState = defender.careerState;\n    handleKO(defender, attacker, events, tick);\n    careerDropped = defender.careerState !== prevState;\n    traineeExited = defender.hasThrownInTowel;\n\n    events.push({\n      type: 'unit_kill' as GameEventType,\n      tick,\n      sourceId: attacker.id,\n      targetId: defender.id,\n      value: damage,\n    });\n  }\n\n  return {\n    hit: true,\n    damage,\n    isCrit,\n    proc: procFired,\n    isKO,\n    careerDropped,\n    traineeExited,\n  };\n}\n\n// ============================================================\n// CAREER RECOVERY \u2014 called by career system on win streak\n// ============================================================\n\n// READS: entity.winStreak, entity.careerState\n// WRITES: entity.careerState, entity.winStreak\nexport function checkCareerRecovery(\n  entity: Entity,\n  events: GameEvent[],\n  tick: number\n): void {\n  if (entity.winStreak < GAME_CONSTANTS.WIN_STREAK_TO_PROMOTE) return;\n  if (entity.hasThrownInTowel) return;\n\n  var currentIndex = CAREER_LADDER.indexOf(entity.careerState);\n  if (currentIndex >= CAREER_LADDER.length - 1) return; // already Champion\n\n  entity.careerState = CAREER_LADDER[currentIndex + 1];\n  entity.winStreak = 0;\n\n  events.push({\n    type: 'career_recovery' as GameEventType,\n    tick,\n    targetId: entity.id,\n    data: { newState: entity.careerState },\n  });\n}\n",
  "packages/engine/src/economy/harvest.ts": "// BOOT ORDER: loaded by server tick loop alongside combat\n// READS: entity.isHarvesting, entity.harvestTarget, player.bling\n// WRITES: entity.isHarvesting, player.bling, node.currentHolderId\n\nimport {\n  Entity,\n  Player,\n  MapNode,\n  GameEvent,\n  GameEventType,\n  Vec2,\n} from '@fist/shared';\n\nimport { GAME_CONSTANTS } from '@fist/shared';\n\n// ============================================================\n// DISTANCE UTILITY\n// ============================================================\n\n// DEPENDS ON: nothing\nfunction distance(a: Vec2, b: Vec2): number {\n  var dx = a.x - b.x;\n  var dy = a.y - b.y;\n  return Math.sqrt(dx * dx + dy * dy);\n}\n\n// ============================================================\n// EFFECTIVE WORKERS FORMULA\n// GDD: effectiveWorkers = floor(3 * sqrt(trainees))\n// Creates soft cap on worker scaling \u2014 prevents spam economy\n// ============================================================\n\n// DEPENDS ON: GAME_CONSTANTS\nexport function getEffectiveWorkers(traineeCount: number): number {\n  return Math.floor(3 * Math.sqrt(traineeCount));\n}\n\n// ============================================================\n// INCOME PER SECOND\n// GDD: yieldPerCycle = effectiveWorkers * BASE_YIELD\n//      incomePerSecond = yieldPerCycle / ROUND_TRIP_S\n// ============================================================\n\n// DEPENDS ON: getEffectiveWorkers, GAME_CONSTANTS\nexport function getIncomePerSecond(traineeCount: number): number {\n  var effective = getEffectiveWorkers(traineeCount);\n  var yieldPerCycle = effective * GAME_CONSTANTS.BASE_YIELD;\n  return yieldPerCycle / GAME_CONSTANTS.ROUND_TRIP_S;\n}\n\n// ============================================================\n// HARVEST TICK\n// Called every server tick for each harvesting trainee\n// Simple state machine: IDLE \u2192 MOVING_TO_NODE \u2192 HARVESTING \u2192 RETURNING \u2192 DROP_OFF\n// ============================================================\n\nexport type HarvestPhase =\n  | 'IDLE'\n  | 'MOVING_TO_NODE'\n  | 'HARVESTING'\n  | 'RETURNING'\n  | 'DROP_OFF';\n\nexport interface HarvestState {\n  phase: HarvestPhase;\n  phaseElapsedS: number;\n  carryingBling: number;\n  targetNodeId: string | null;\n}\n\n// Attach to entity \u2014 stored in entity.memory (re-using slot) or extend Entity\n// For now we store on a parallel map keyed by entity id\n\n// READS: harvestStates, node positions, base positions\n// WRITES: harvestStates, player.bling, events[]\nexport function tickHarvest(\n  entity: Entity,\n  state: HarvestState,\n  node: MapNode | null,\n  player: Player,\n  deltaS: number,\n  events: GameEvent[],\n  tick: number\n): void {\n  if (!entity.isTrainee || !entity.isAlive) return;\n\n  state.phaseElapsedS += deltaS;\n\n  switch (state.phase) {\n\n    case 'IDLE':\n      // Assign to nearest available node \u2014 handled by economy system\n      // When node is assigned externally, transition to MOVING_TO_NODE\n      if (state.targetNodeId && node) {\n        state.phase = 'MOVING_TO_NODE';\n        state.phaseElapsedS = 0;\n      }\n      break;\n\n    case 'MOVING_TO_NODE':\n      // Simplified: movement is instant in simulation (visual path handled by client)\n      // Arrival after HARVEST_TIME_S / 2 (half the round trip is travel)\n      if (state.phaseElapsedS >= GAME_CONSTANTS.HARVEST_TIME_S) {\n        state.phase = 'HARVESTING';\n        state.phaseElapsedS = 0;\n      }\n      break;\n\n    case 'HARVESTING':\n      // Harvesting takes HARVEST_TIME_S total at the node\n      if (state.phaseElapsedS >= GAME_CONSTANTS.HARVEST_TIME_S) {\n        state.carryingBling = GAME_CONSTANTS.BASE_YIELD;\n        state.phase = 'RETURNING';\n        state.phaseElapsedS = 0;\n      }\n      break;\n\n    case 'RETURNING':\n      // Return trip\n      if (state.phaseElapsedS >= GAME_CONSTANTS.DROP_OFF_TIME_S) {\n        state.phase = 'DROP_OFF';\n        state.phaseElapsedS = 0;\n      }\n      break;\n\n    case 'DROP_OFF':\n      // Deposit Bling and restart cycle\n      var amount = state.carryingBling;\n      player.bling += amount;\n      state.carryingBling = 0;\n      state.phase = 'MOVING_TO_NODE';\n      state.phaseElapsedS = 0;\n\n      events.push({\n        type: 'bling_harvested' as GameEventType,\n        tick,\n        sourceId: entity.id,\n        targetId: player.id,\n        value: amount,\n      });\n      break;\n  }\n}\n\n// ============================================================\n// CENTER NODE HOLD \u2014 accumulate hold time, award center bonus\n// ============================================================\n\n// READS: node.currentHolderId, player.totalCenterTimeS\n// WRITES: player.totalCenterTimeS, player.bling\nexport function tickCenterHold(\n  centerNode: MapNode,\n  players: Record<string, Player>,\n  entities: Record<string, Entity>,\n  deltaS: number\n): void {\n  // Determine if a player holds center\n  // Held if: player has a living non-trainee fighter within CAGE_CONTROL_RADIUS\n  // AND no enemy unit is within CAGE_CONTROL_RADIUS\n\n  var unitsNearCenter: Record<string, string[]> = {}; // playerId \u2192 entityIds\n\n  Object.values(entities).forEach(function(e) {\n    if (!e.isAlive || e.isTrainee) return;\n    var dist = distance(e.position, centerNode.position);\n    if (dist <= GAME_CONSTANTS.CAGE_CONTROL_RADIUS) {\n      if (!unitsNearCenter[e.playerId]) unitsNearCenter[e.playerId] = [];\n      unitsNearCenter[e.playerId].push(e.id);\n    }\n  });\n\n  var playerIdsNearCenter = Object.keys(unitsNearCenter);\n\n  // Only one player near center = they hold it\n  if (playerIdsNearCenter.length === 1) {\n    var holderId = playerIdsNearCenter[0];\n    centerNode.currentHolderId = holderId;\n\n    var holder = players[holderId];\n    if (holder) {\n      holder.totalCenterTimeS += deltaS;\n      holder.bling += GAME_CONSTANTS.CENTER_BONUS_PER_SEC * deltaS;\n\n      // Accumulate in node record too\n      if (!centerNode.accumulatedHoldTime[holderId]) {\n        centerNode.accumulatedHoldTime[holderId] = 0;\n      }\n      centerNode.accumulatedHoldTime[holderId] += deltaS;\n    }\n  } else {\n    // Contested or empty \u2014 no one holds\n    centerNode.currentHolderId = null;\n  }\n}\n\n// ============================================================\n// SPEND BLING \u2014 validates and deducts\n// Returns true if purchase succeeded\n// ============================================================\n\n// READS: player.bling\n// WRITES: player.bling, events[]\nexport function spendBling(\n  player: Player,\n  amount: number,\n  events: GameEvent[],\n  tick: number\n): boolean {\n  if (player.bling < amount) return false;\n\n  player.bling -= amount;\n\n  events.push({\n    type: 'bling_spent' as GameEventType,\n    tick,\n    sourceId: player.id,\n    value: amount,\n  });\n\n  return true;\n}\n\n// ============================================================\n// CONFIDENCE PASSIVE DECAY \u2014 called every CONFIDENCE_DECAY_INTERVAL_S\n// ============================================================\n\n// READS: entity.confidence\n// WRITES: entity.confidence\nexport function tickConfidenceDecay(entity: Entity): void {\n  entity.confidence = Math.max(\n    0,\n    entity.confidence - GAME_CONSTANTS.CONFIDENCE_PASSIVE_DECAY\n  );\n}\n",
  "packages/engine/src/index.ts": "export * from './combat/resolver';\nexport * from './economy/harvest';\n",
  "packages/commentary/package.json": "{\n  \"name\": \"@fist/commentary\",\n  \"version\": \"0.1.0\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"scripts\": {\n    \"build\": \"tsc\"\n  },\n  \"dependencies\": {\n    \"@fist/shared\": \"*\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"^5.6.0\"\n  }\n}\n",
  "packages/commentary/src/index.ts": "// BOOT ORDER: loaded by server after combat and economy\n// READS: GameEvent[], entity states\n// WRITES: commentary output lines (broadcast to clients)\n\nimport {\n  GameEvent,\n  GameEventType,\n  CommentaryTier,\n  CareerState,\n} from '@fist/shared';\n\nimport { GAME_CONSTANTS } from '@fist/shared';\n\n// ============================================================\n// VOICE TYPES\n// ============================================================\n\nexport type Voice =\n  | 'PROFESSIONAL_CASTER'\n  | 'FIGHT_PROMOTER'\n  | 'STREET_COMMENTATOR'\n  | 'HISTORIAN'\n  | 'STREAM_CHAT';\n\nexport interface CommentaryLine {\n  voice: Voice;\n  text: string;\n  tier: CommentaryTier;\n  isViralClip: boolean;\n  clipCaption: string | null;\n}\n\n// ============================================================\n// NARRATIVE STATES\n// ============================================================\n\nexport type NarrativeState =\n  | 'underdog_rise'\n  | 'unstoppable_monster'\n  | 'technical_masterclass'\n  | 'desperate_survival'\n  | 'public_execution'\n  | 'viral_moment'\n  | 'tragic_collapse'\n  | 'redemption_arc';\n\n// ============================================================\n// LINE TABLES \u2014 indexed by [voice][event_type]\n// Extend these arrays to add more flavor variety\n// ============================================================\n\nvar LINES: Partial<Record<Voice, Partial<Record<GameEventType, string[]>>>> = {\n\n  PROFESSIONAL_CASTER: {\n    unit_kill:      ['And he's down.', 'Clean finish.', 'That's a KO.'],\n    career_drop:    ['Career state declining. This is significant.', 'He's dropped a tier.'],\n    trainee_exit:   ['The trainee has thrown in the towel.', 'That young man is done for today.'],\n    crit_hit:       ['Flush hit. Perfect contact.', 'That landed clean.'],\n    comeback:       ['He's finding his range again.', 'A shift in momentum here.'],\n    career_recovery:['He's earning his way back.', 'Tier recovery. He's fighting back.'],\n    cage_control_achieved: ['Center control established.', 'They own the middle.'],\n    proc_chain:     ['Status effect applied.', 'Compound pressure now.'],\n  },\n\n  FIGHT_PROMOTER: {\n    unit_kill:      ['THAT IS WHAT I PAID FOR!', 'SOMEBODY STOP THE FIGHT!', 'YYYYES!'],\n    career_drop:    ['HE'S FALLING APART!', 'The wheels are coming OFF!'],\n    trainee_exit:   ['THE KID IS DONE! THE KID IS DONE!', 'THROW THE TOWEL! IT'S OVER!'],\n    crit_hit:       ['OHHHHH!', 'THAT'S THE SHOT!', 'GOODNIGHT!'],\n    comeback:       ['HE'S BACK BABY!', 'DON'T COUNT HIM OUT!'],\n    cage_control_achieved: ['THEY OWN THIS FIGHT NOW! THEY OWN THE MIDDLE!'],\n    proc_chain:     ['IT'S RAINING HITS!', 'HE CAN'T MISS!'],\n  },\n\n  STREET_COMMENTATOR: {\n    unit_kill:      ['Yo he's out.', 'Bro got folded.', 'He's sleep.'],\n    career_drop:    ['Bro he's shook right now.', 'He lost his whole swag.'],\n    trainee_exit:   ['He walked. He actually just walked.', 'Nah he said I'm good.'],\n    crit_hit:       ['YOOO.', 'Bruh that was nasty.', 'He caught him.'],\n    comeback:       ['He back tho.', 'Nah don't sleep on him.'],\n    cage_control_achieved: ['They got the middle locked down.', 'Nobody's getting through.'],\n    proc_chain:     ['He's bleeding out here.', 'It's getting ugly.'],\n  },\n\n  HISTORIAN: {\n    unit_kill:      ['A decisive finish, in the tradition of the great ones.', 'The fight is over. History records another KO.'],\n    career_drop:    ['Even legends have fallen this way.', 'The demotion is brutal \u2014 but the sport demands it.'],\n    trainee_exit:   ['The youngest have always been the most expendable.', 'He gave what he could. The mat remembers.'],\n    crit_hit:       ['That's pure Ali footwork paying off.', 'A Karelin-level transfer of force.'],\n    comeback:       ['Every champion has survived this moment.', 'The great ones find a way.'],\n    cage_control_achieved: ['Territorial dominance \u2014 the oldest strategy in combat.'],\n    proc_chain:     ['He's going full Sakuraba \u2014 psychological warfare.'],\n  },\n\n  STREAM_CHAT: {\n    unit_kill:      ['HE'S DEAD', 'LMAOOOO', 'GG', 'OMEGALUL', 'F'],\n    career_drop:    ['HE DROPPED??', 'WAIT WHAT', 'NOOOO', 'DEVOLVED LMAO'],\n    trainee_exit:   ['HE QUIT LMAOOO', 'BYE', 'TRAINEE NO', 'THREW THE TOWEL'],\n    crit_hit:       ['CLIP THAT', 'WHAT', 'POGGERS', 'INSANE'],\n    comeback:       ['HE'S BACK???', 'WAIT WAIT WAIT', 'NO WAY'],\n    cage_control_achieved: ['CAGE CONTROL', 'THEY GOT MIDDLE', 'ITS OVER'],\n    proc_chain:     ['BLEED STACK LOL', 'PROC CITY', 'ITS CHAOS'],\n  },\n};\n\n// ============================================================\n// COMMENTARY ENGINE\n// ============================================================\n\nexport class CommentaryEngine {\n  private voices: Voice[] = [\n    'PROFESSIONAL_CASTER',\n    'FIGHT_PROMOTER',\n    'STREET_COMMENTATOR',\n    'HISTORIAN',\n    'STREAM_CHAT',\n  ];\n\n  private voiceIndex: number = 0;\n  private cooldowns: Partial<Record<CommentaryTier, number>> = {};\n  private narrativeState: NarrativeState = 'viral_moment';\n  private recentLines: string[] = [];\n\n  // READS: events[], cooldowns\n  // WRITES: cooldowns, voiceIndex, recentLines\n  processEvents(events: GameEvent[], deltaS: number): CommentaryLine[] {\n    var output: CommentaryLine[] = [];\n\n    // Tick down cooldowns\n    Object.keys(this.cooldowns).forEach(function(tier) {\n      var t = tier as CommentaryTier;\n      var cd = this.cooldowns[t];\n      if (cd !== undefined) {\n        this.cooldowns[t] = Math.max(0, cd - deltaS);\n      }\n    }, this);\n\n    events.forEach(function(event) {\n      var tier = this.getEventTier(event.type);\n      if (!tier) return;\n\n      var cdSeconds = GAME_CONSTANTS.COMMENTARY_COOLDOWNS_S[tier];\n      if ((this.cooldowns[tier] ?? 0) > 0) return;\n\n      var line = this.generateLine(event, tier);\n      if (!line) return;\n\n      this.cooldowns[tier] = cdSeconds;\n      output.push(line);\n\n      // Rotate voice after T3+ events\n      if (tier === CommentaryTier.T3 || tier === CommentaryTier.T4 || tier === CommentaryTier.T5) {\n        this.voiceIndex = (this.voiceIndex + 1) % this.voices.length;\n      }\n    }, this);\n\n    return output;\n  }\n\n  // DEPENDS ON: LINES, getViralCaption\n  private generateLine(event: GameEvent, tier: CommentaryTier): CommentaryLine | null {\n    var voice = this.voices[this.voiceIndex];\n    var voiceLines = LINES[voice];\n    if (!voiceLines) return null;\n\n    var eventLines = voiceLines[event.type];\n    if (!eventLines || eventLines.length === 0) return null;\n\n    var text = eventLines[Math.floor(Math.random() * eventLines.length)];\n\n    // Avoid immediate repeats\n    if (this.recentLines.includes(text)) {\n      var alt = eventLines.find(function(l) { return !this.recentLines.includes(l); }, this);\n      if (alt) text = alt;\n    }\n\n    this.recentLines.push(text);\n    if (this.recentLines.length > 10) this.recentLines.shift();\n\n    var isViralClip = tier === CommentaryTier.T3 || tier === CommentaryTier.T4 || tier === CommentaryTier.T5;\n    var clipCaption = isViralClip ? this.getViralCaption(event) : null;\n\n    return { voice, text, tier, isViralClip, clipCaption };\n  }\n\n  // VIRAL CLIP FORMAT: [FIGHTER] just [ACTION] [TARGET] in [VENUE] \ud83d\udc80 #FIST #Worldstar\n  private getViralCaption(event: GameEvent): string {\n    switch (event.type) {\n      case 'unit_kill':\n        return `FIGHTER just GOT DROPPED \ud83d\udc80 #FIST #Worldstar`;\n      case 'career_drop':\n        return `HE WAS A CHAMPION LAST MATCH \ud83d\udc80 #FIST #Worldstar`;\n      case 'trainee_exit':\n        return `HE'S DONE. THAT'S IT. HE'S DONE. \ud83d\udc80 #FIST #Worldstar`;\n      case 'comeback':\n        return `THIS GUY FOUGHT HIS WAY BACK FROM NOTHING \ud83d\udc80 #FIST #Worldstar`;\n      case 'proc_chain':\n        return `IT'S CHAOS IN THE ${event.data?.venue ?? 'ARENA'} \ud83d\udc80 #FIST #Worldstar`;\n      default:\n        return `SOMETHING JUST HAPPENED \ud83d\udc80 #FIST #Worldstar`;\n    }\n  }\n\n  // Map event types to commentary tiers\n  private getEventTier(type: GameEventType): CommentaryTier | null {\n    var T1: GameEventType[] = ['crit_hit', 'bling_harvested', 'proc_chain'];\n    var T2: GameEventType[] = ['career_drop', 'career_recovery', 'cage_control_achieved'];\n    var T3: GameEventType[] = ['unit_kill', 'trainee_exit', 'bleed_out'];\n    var T4: GameEventType[] = ['comeback', 'comeback_arc', 'champion_at_risk'];\n    var T5: GameEventType[] = ['match_end', 'confidence_collapse'];\n\n    if (T1.includes(type)) return CommentaryTier.T1;\n    if (T2.includes(type)) return CommentaryTier.T2;\n    if (T3.includes(type)) return CommentaryTier.T3;\n    if (T4.includes(type)) return CommentaryTier.T4;\n    if (T5.includes(type)) return CommentaryTier.T5;\n    return null;\n  }\n\n  updateNarrative(state: NarrativeState): void {\n    this.narrativeState = state;\n  }\n}\n",
  "packages/server/package.json": "{\n  \"name\": \"@fist/server\",\n  \"version\": \"0.1.0\",\n  \"main\": \"dist/index.js\",\n  \"scripts\": {\n    \"dev\": \"ts-node src/index.ts\",\n    \"build\": \"tsc\"\n  },\n  \"dependencies\": {\n    \"@fist/shared\": \"*\",\n    \"@fist/engine\": \"*\",\n    \"@fist/commentary\": \"*\",\n    \"socket.io\": \"^4.7.0\",\n    \"express\": \"^4.18.0\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"^5.6.0\",\n    \"ts-node\": \"^10.9.0\",\n    \"@types/express\": \"^4.17.0\",\n    \"@types/node\": \"^20.0.0\"\n  }\n}\n",
  "packages/server/tsconfig.json": "{\n  \"extends\": \"../../tsconfig.json\",\n  \"compilerOptions\": {\n    \"rootDir\": \"src\",\n    \"outDir\": \"dist\"\n  },\n  \"references\": [\n    { \"path\": \"../shared\" },\n    { \"path\": \"../engine\" },\n    { \"path\": \"../commentary\" }\n  ],\n  \"include\": [\"src\"]\n}\n",
  "packages/server/src/game/state.ts": "// BOOT ORDER: loaded before tick loop\n// READS: nothing on init\n// WRITES: GameState (creates it)\n\nimport {\n  GameState,\n  Entity,\n  Player,\n  MapNode,\n  Vec2,\n  Discipline,\n  CareerState,\n  AIState,\n} from '@fist/shared';\n\nimport { GAME_CONSTANTS, TIER_STATS } from '@fist/shared';\n\n// ============================================================\n// ID GENERATOR\n// ============================================================\n\nvar _idCounter = 0;\nexport function makeId(prefix: string): string {\n  _idCounter++;\n  return `${prefix}_${_idCounter}_${Date.now()}`;\n}\n\n// ============================================================\n// CREATE ENTITY\n// ============================================================\n\n// DEPENDS ON: TIER_STATS, CAREER_MULTIPLIERS\nexport function createEntity(\n  playerId: string,\n  discipline: Discipline,\n  tier: 1 | 2 | 3 | 4 | 5,\n  position: Vec2,\n  isTrainee: boolean = false\n): Entity {\n  var tierKey = `T${tier}` as keyof typeof TIER_STATS;\n  var stats = TIER_STATS[tierKey];\n\n  return {\n    id: makeId('ent'),\n    playerId,\n    discipline,\n    tier,\n    careerState: isTrainee ? CareerState.TRAINEE : CareerState.FIGHTER,\n    position: { ...position },\n    velocity: { x: 0, y: 0 },\n    confidence: isTrainee ? 0.3 : 0.6,\n    hp: stats.hp,\n    maxHp: stats.hp,\n    baseDamage: stats.baseDamage,\n    defense: stats.defense,\n    speed: 5.0,\n    cooldowns: {},\n    activeProcs: [],\n    aiState: AIState.AGGRESSIVE,\n    memory: {\n      lastHitById: null,\n      lastKOById: null,\n      recentMoves: [],\n      failedAbilities: [],\n    },\n    isTrainee,\n    isHarvesting: isTrainee,\n    harvestTarget: null,\n    winStreak: 0,\n    koCount: 0,\n    struggleMeter: 0,\n    chainCount: 0,\n    isAlive: true,\n    hasThrownInTowel: false,\n  };\n}\n\n// ============================================================\n// CREATE PLAYER\n// ============================================================\n\nexport function createPlayer(\n  id: string,\n  discipline: Discipline,\n  basePosition: Vec2\n): Player {\n  return {\n    id,\n    discipline,\n    bling: 0,\n    respect: 0,\n    totalCenterTimeS: 0,\n    entities: [],\n    basePosition,\n    isConnected: true,\n  };\n}\n\n// ============================================================\n// CREATE MAP NODE\n// ============================================================\n\nexport function createNode(\n  id: string,\n  position: Vec2,\n  isContested: boolean,\n  isCenter: boolean\n): MapNode {\n  return {\n    id,\n    position,\n    isContested,\n    isCenter,\n    currentHolderId: null,\n    accumulatedHoldTime: {},\n  };\n}\n\n// ============================================================\n// INIT GAME STATE\n// Creates a fresh authoritative match state\n// ============================================================\n\nexport function createGameState(\n  playerDisciplines: Record<string, Discipline>\n): GameState {\n  var players: Record<string, Player> = {};\n  var entities: Record<string, Entity> = {};\n\n  // Arrange player bases evenly around the map\n  // Simple 5-position radial layout \u2014 center at (50, 50), radius 35\n  var basePositions: Vec2[] = [\n    { x: 50, y: 15 },\n    { x: 82, y: 35 },\n    { x: 70, y: 75 },\n    { x: 30, y: 75 },\n    { x: 18, y: 35 },\n  ];\n\n  var playerIds = Object.keys(playerDisciplines);\n\n  playerIds.forEach(function(pid, idx) {\n    var basePos = basePositions[idx] ?? { x: 50, y: 50 };\n    var player = createPlayer(pid, playerDisciplines[pid], basePos);\n    players[pid] = player;\n\n    // Spawn starting trainees near base\n    for (var t = 0; t < GAME_CONSTANTS.TRAINEE_START; t++) {\n      var trainee = createEntity(\n        pid,\n        playerDisciplines[pid],\n        1,\n        { x: basePos.x + (t - 1) * 3, y: basePos.y + 2 },\n        true\n      );\n      entities[trainee.id] = trainee;\n      player.entities.push(trainee.id);\n    }\n  });\n\n  // Create nodes\n  // 3 contested (center cluster), 4 uncontested (corners/sides)\n  var nodes: Record<string, MapNode> = {};\n\n  var nodeConfigs = [\n    { id: 'node_center',  pos: { x: 50, y: 50 }, contested: true,  center: true  },\n    { id: 'node_c1',     pos: { x: 40, y: 42 }, contested: true,  center: false },\n    { id: 'node_c2',     pos: { x: 60, y: 42 }, contested: true,  center: false },\n    { id: 'node_s1',     pos: { x: 20, y: 20 }, contested: false, center: false },\n    { id: 'node_s2',     pos: { x: 80, y: 20 }, contested: false, center: false },\n    { id: 'node_s3',     pos: { x: 80, y: 80 }, contested: false, center: false },\n    { id: 'node_s4',     pos: { x: 20, y: 80 }, contested: false, center: false },\n  ];\n\n  nodeConfigs.forEach(function(cfg) {\n    nodes[cfg.id] = createNode(cfg.id, cfg.pos, cfg.contested, cfg.center);\n  });\n\n  return {\n    tick: 0,\n    matchElapsedS: 0,\n    matchDurationS: GAME_CONSTANTS.MATCH_DURATION_S,\n    players,\n    entities,\n    nodes,\n    events: [],\n    phase: 'WAR',\n    winnerId: null,\n  };\n}\n\n// ============================================================\n// DETERMINE WINNER \u2014 most accumulated center time at bell\n// ============================================================\n\n// READS: players[].totalCenterTimeS\n// WRITES: state.winnerId, state.phase\nexport function checkMatchEnd(state: GameState): void {\n  if (state.matchElapsedS < state.matchDurationS) return;\n  if (state.phase === 'ENDED') return;\n\n  state.phase = 'ENDED';\n\n  var winner = Object.values(state.players).reduce(function(best, player) {\n    return player.totalCenterTimeS > best.totalCenterTimeS ? player : best;\n  });\n\n  state.winnerId = winner.id;\n\n  state.events.push({\n    type: 'match_end',\n    tick: state.tick,\n    sourceId: winner.id,\n    value: winner.totalCenterTimeS,\n  });\n}\n",
  "packages/server/src/game/loop.ts": "// BOOT ORDER: entry point for simulation\n// READS: GameState, incoming commands\n// WRITES: GameState each tick, broadcasts Snapshot\n\nimport {\n  GameState,\n  Entity,\n  Snapshot,\n  Command,\n  ActionType,\n  CareerState,\n} from '@fist/shared';\n\nimport { GAME_CONSTANTS } from '@fist/shared';\n\nimport {\n  resolveAttack,\n  checkCareerRecovery,\n  tickProcs,\n  tickConfidenceDecay,\n} from '@fist/engine';\n\nimport {\n  tickHarvest,\n  tickCenterHold,\n  HarvestState,\n} from '@fist/engine';\n\nimport { CommentaryEngine } from '@fist/commentary';\n\nimport { checkMatchEnd } from './state';\n\n// ============================================================\n// TICK LOOP\n// ============================================================\n\nexport class GameLoop {\n  private state: GameState;\n  private commentary: CommentaryEngine;\n  private harvestStates: Map<string, HarvestState>;\n  private commandQueues: Map<string, Command[]>;\n  private confidenceDecayTimer: number = 0;\n  private onSnapshot: (snapshot: Snapshot) => void;\n  private intervalHandle: ReturnType<typeof setInterval> | null = null;\n\n  constructor(\n    state: GameState,\n    onSnapshot: (snapshot: Snapshot) => void\n  ) {\n    this.state = state;\n    this.commentary = new CommentaryEngine();\n    this.harvestStates = new Map();\n    this.commandQueues = new Map();\n    this.onSnapshot = onSnapshot;\n\n    // Init harvest states for all starting trainees\n    Object.values(state.entities).forEach(function(entity) {\n      if (entity.isTrainee) {\n        this.harvestStates.set(entity.id, {\n          phase: 'MOVING_TO_NODE',\n          phaseElapsedS: 0,\n          carryingBling: 0,\n          targetNodeId: 'node_s1', // nearest safe node \u2014 simplified\n        });\n      }\n    }, this);\n  }\n\n  // ============================================================\n  // START / STOP\n  // ============================================================\n\n  start(): void {\n    this.intervalHandle = setInterval(\n      this.tick.bind(this),\n      GAME_CONSTANTS.TICK_MS\n    );\n  }\n\n  stop(): void {\n    if (this.intervalHandle) {\n      clearInterval(this.intervalHandle);\n      this.intervalHandle = null;\n    }\n  }\n\n  // ============================================================\n  // ENQUEUE PLAYER COMMAND\n  // ============================================================\n\n  // READS: commandQueues\n  // WRITES: commandQueues\n  enqueueCommand(command: Command): void {\n    var queue = this.commandQueues.get(command.unitId) ?? [];\n\n    // Enforce max queue depth and delay\n    if (queue.length >= GAME_CONSTANTS.AI_MAX_QUEUE) {\n      queue.shift(); // drop oldest\n    }\n\n    queue.push(command);\n    this.commandQueues.set(command.unitId, queue);\n  }\n\n  // ============================================================\n  // MAIN TICK\n  // ============================================================\n\n  // READS: state, harvestStates, commandQueues\n  // WRITES: state (all subsystems), broadcasts snapshot\n  private tick(): void {\n    var deltaS = GAME_CONSTANTS.TICK_MS / 1000;\n    var state = this.state;\n\n    if (state.phase === 'ENDED') return;\n\n    state.tick++;\n    state.matchElapsedS += deltaS;\n    state.events = []; // clear events from last tick\n\n    // 1. Process player commands\n    this.processCommands(deltaS);\n\n    // 2. Tick harvest for all trainees\n    this.processHarvest(deltaS);\n\n    // 3. Tick center hold (King of the Hill objective)\n    var centerNode = Object.values(state.nodes).find(function(n) { return n.isCenter; });\n    if (centerNode) {\n      tickCenterHold(centerNode, state.players, state.entities, deltaS);\n    }\n\n    // 4. Tick active procs on all entities\n    Object.values(state.entities).forEach(function(entity) {\n      if (entity.isAlive) tickProcs(entity, deltaS);\n    });\n\n    // 5. Tick cooldowns on all entities\n    this.tickCooldowns(deltaS);\n\n    // 6. Confidence passive decay\n    this.confidenceDecayTimer += deltaS;\n    if (this.confidenceDecayTimer >= GAME_CONSTANTS.CONFIDENCE_DECAY_INTERVAL_S) {\n      this.confidenceDecayTimer = 0;\n      Object.values(state.entities).forEach(function(entity) {\n        if (entity.isAlive) tickConfidenceDecay(entity);\n      });\n    }\n\n    // 7. Check career recovery for all fighters\n    Object.values(state.entities).forEach(function(entity) {\n      if (entity.isAlive && !entity.isTrainee) {\n        checkCareerRecovery(entity, state.events, state.tick);\n      }\n    });\n\n    // 8. Check match end condition\n    checkMatchEnd(state);\n\n    // 9. Process commentary\n    var commentary = this.commentary.processEvents(state.events, deltaS);\n\n    // 10. Build and broadcast snapshot\n    var snapshot = this.buildSnapshot(commentary);\n    this.onSnapshot(snapshot);\n  }\n\n  // ============================================================\n  // PROCESS COMMANDS\n  // ============================================================\n\n  // READS: commandQueues, state.entities\n  // WRITES: state.entities (position, attacks), state.events\n  private processCommands(deltaS: number): void {\n    var state = this.state;\n\n    this.commandQueues.forEach(function(queue, unitId) {\n      if (queue.length === 0) return;\n\n      var entity = state.entities[unitId];\n      if (!entity || !entity.isAlive) return;\n\n      var command = queue[0];\n\n      switch (command.type) {\n        case ActionType.MOVE:\n          if (command.targetPos) {\n            // Move toward target position\n            var dx = command.targetPos.x - entity.position.x;\n            var dy = command.targetPos.y - entity.position.y;\n            var dist = Math.sqrt(dx * dx + dy * dy);\n\n            if (dist < 0.5) {\n              queue.shift(); // arrived\n            } else {\n              var speed = entity.speed * deltaS;\n              entity.position.x += (dx / dist) * speed;\n              entity.position.y += (dy / dist) * speed;\n            }\n          }\n          break;\n\n        case ActionType.PUNCH:\n        case ActionType.KICK:\n        case ActionType.GRAPPLE: {\n          var cdKey = command.type;\n          var cd = entity.cooldowns[cdKey] ?? 0;\n          if (cd > 0) break; // still on cooldown\n\n          if (command.targetId) {\n            var target = state.entities[command.targetId];\n            if (target && target.isAlive) {\n              var result = resolveAttack(entity, target, state.events, state.tick);\n\n              if (result.hit && result.isKO) {\n                entity.winStreak++;\n              }\n\n              // Set cooldown\n              var cooldownTime =\n                command.type === ActionType.PUNCH ? GAME_CONSTANTS.CD_PUNCH :\n                command.type === ActionType.KICK  ? GAME_CONSTANTS.CD_KICK  :\n                GAME_CONSTANTS.CD_GRAPPLE;\n\n              entity.cooldowns[cdKey] = cooldownTime;\n            }\n          }\n\n          queue.shift();\n          break;\n        }\n\n        default:\n          queue.shift();\n          break;\n      }\n    });\n  }\n\n  // ============================================================\n  // PROCESS HARVEST\n  // ============================================================\n\n  // READS: harvestStates, state.entities, state.nodes, state.players\n  // WRITES: harvestStates, state.players[].bling, state.events\n  private processHarvest(deltaS: number): void {\n    var state = this.state;\n\n    state.entities && Object.values(state.entities).forEach(function(entity) {\n      if (!entity.isTrainee || !entity.isAlive) return;\n\n      var harvestState = this.harvestStates.get(entity.id);\n      if (!harvestState) return;\n\n      var node = harvestState.targetNodeId\n        ? state.nodes[harvestState.targetNodeId] ?? null\n        : null;\n\n      var player = state.players[entity.playerId];\n      if (!player) return;\n\n      tickHarvest(\n        entity,\n        harvestState,\n        node,\n        player,\n        deltaS,\n        state.events,\n        state.tick\n      );\n    }, this);\n  }\n\n  // ============================================================\n  // TICK COOLDOWNS\n  // ============================================================\n\n  // READS: entity.cooldowns\n  // WRITES: entity.cooldowns (decrement each tick)\n  private tickCooldowns(deltaS: number): void {\n    Object.values(this.state.entities).forEach(function(entity) {\n      Object.keys(entity.cooldowns).forEach(function(key) {\n        var k = key as ActionType;\n        var current = entity.cooldowns[k] ?? 0;\n        if (current > 0) {\n          entity.cooldowns[k] = Math.max(0, current - deltaS);\n        }\n      });\n    });\n  }\n\n  // ============================================================\n  // BUILD SNAPSHOT \u2014 serialized state for clients\n  // ============================================================\n\n  // READS: state\n  // WRITES: nothing \u2014 pure serialization\n  private buildSnapshot(\n    _commentary: ReturnType<CommentaryEngine['processEvents']>\n  ): Snapshot {\n    var state = this.state;\n\n    var playerData: Snapshot['players'] = {};\n    Object.values(state.players).forEach(function(p) {\n      playerData[p.id] = {\n        bling: p.bling,\n        respect: p.respect,\n        totalCenterTimeS: p.totalCenterTimeS,\n      };\n    });\n\n    var entitySnapshots = Object.values(state.entities).map(function(e) {\n      return {\n        id: e.id,\n        pos: { ...e.position },\n        hp: e.hp,\n        maxHp: e.maxHp,\n        careerState: e.careerState,\n        aiState: e.aiState,\n        confidence: e.confidence,\n        isAlive: e.isAlive,\n        isHarvesting: e.isHarvesting,\n        activeProcs: e.activeProcs.map(function(p) { return p.type; }),\n      };\n    });\n\n    return {\n      tick: state.tick,\n      matchElapsedS: state.matchElapsedS,\n      players: playerData,\n      entities: entitySnapshots,\n      events: [...state.events],\n    };\n  }\n\n  getState(): GameState {\n    return this.state;\n  }\n}\n",
  "packages/server/src/index.ts": "// BOOT ORDER: entry point \u2014 runs last, starts everything\n// READS: nothing on start\n// WRITES: starts HTTP server, opens WebSocket\n\nimport express from 'express';\nimport { createServer } from 'http';\nimport { Server, Socket } from 'socket.io';\nimport { Discipline, Command } from '@fist/shared';\nimport { createGameState } from './game/state';\nimport { GameLoop } from './game/loop';\n\nvar app = express();\nvar httpServer = createServer(app);\n\nvar io = new Server(httpServer, {\n  cors: {\n    origin: '*', // tighten this for production\n    methods: ['GET', 'POST'],\n  },\n});\n\n// ============================================================\n// MATCH REGISTRY\n// One match per room for now \u2014 expandable to multiple rooms\n// ============================================================\n\nvar activeLoops: Map<string, GameLoop> = new Map();\nvar pendingPlayers: Map<string, Discipline> = new Map(); // socketId \u2192 discipline\nvar MATCH_ROOM = 'match_1';\nvar MIN_PLAYERS_TO_START = 2;\n\n// ============================================================\n// SOCKET HANDLERS\n// ============================================================\n\nio.on('connection', function(socket: Socket) {\n  console.log(`[FYTECRAFT] Client connected: ${socket.id}`);\n\n  // Client sends their discipline choice\n  socket.on('join', function(data: { discipline: Discipline }) {\n    if (!Object.values(Discipline).includes(data.discipline)) {\n      socket.emit('error', { message: 'Invalid discipline.' });\n      return;\n    }\n\n    pendingPlayers.set(socket.id, data.discipline);\n    socket.join(MATCH_ROOM);\n\n    console.log(`[FYTECRAFT] ${socket.id} joined as ${data.discipline} (${pendingPlayers.size} waiting)`);\n\n    socket.emit('joined', {\n      playerId: socket.id,\n      discipline: data.discipline,\n      waitingFor: Math.max(0, MIN_PLAYERS_TO_START - pendingPlayers.size),\n    });\n\n    // Start match when enough players\n    if (pendingPlayers.size >= MIN_PLAYERS_TO_START && !activeLoops.has(MATCH_ROOM)) {\n      startMatch();\n    }\n  });\n\n  // Client sends a command (move, attack, ability)\n  socket.on('command', function(cmd: Command) {\n    var loop = activeLoops.get(MATCH_ROOM);\n    if (!loop) return;\n\n    // Stamp server-side and enqueue\n    cmd.timestamp = Date.now();\n    loop.enqueueCommand(cmd);\n  });\n\n  socket.on('disconnect', function() {\n    console.log(`[FYTECRAFT] Client disconnected: ${socket.id}`);\n    pendingPlayers.delete(socket.id);\n\n    var loop = activeLoops.get(MATCH_ROOM);\n    if (loop) {\n      var state = loop.getState();\n      var player = state.players[socket.id];\n      if (player) player.isConnected = false;\n    }\n  });\n});\n\n// ============================================================\n// START MATCH\n// ============================================================\n\nfunction startMatch(): void {\n  var playerDisciplines: Record<string, Discipline> = {};\n  pendingPlayers.forEach(function(discipline, socketId) {\n    playerDisciplines[socketId] = discipline;\n  });\n  pendingPlayers.clear();\n\n  var state = createGameState(playerDisciplines);\n\n  var loop = new GameLoop(state, function(snapshot) {\n    // Broadcast snapshot to all clients in the room every tick\n    io.to(MATCH_ROOM).emit('snapshot', snapshot);\n  });\n\n  activeLoops.set(MATCH_ROOM, loop);\n  loop.start();\n\n  console.log(`[FYTECRAFT] Match started with ${Object.keys(playerDisciplines).length} players`);\n  io.to(MATCH_ROOM).emit('match_start', { matchDurationS: state.matchDurationS });\n}\n\n// ============================================================\n// HEALTH CHECK\n// ============================================================\n\napp.get('/health', function(_req, res) {\n  res.json({\n    status: 'ok',\n    version: '0.1.0',\n    activeMatches: activeLoops.size,\n    pendingPlayers: pendingPlayers.size,\n  });\n});\n\n// ============================================================\n// START SERVER\n// ============================================================\n\nvar PORT = process.env.PORT ? parseInt(process.env.PORT) : 3001;\n\nhttpServer.listen(PORT, function() {\n  console.log(`[FYTECRAFT] Server running on port ${PORT}`);\n  console.log(`[FYTECRAFT] Health: http://localhost:${PORT}/health`);\n});\n\nexport default app;\n"
};

function write(relPath, content) {
  var full = path.join(process.cwd(), relPath);
  var dir = path.dirname(full);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(full, content, 'utf8');
  console.log('  wrote: ' + relPath);
}

console.log('\n[FIST SETUP] Writing ' + Object.keys(FILES).length + ' files to: ' + process.cwd() + '\n');

Object.keys(FILES).forEach(function(relPath) {
  write(relPath, FILES[relPath]);
});

console.log('\n[FIST SETUP] Done. All 19 files written.');
console.log('');
console.log('Next steps:');
console.log('  1.  npm install');
console.log('  2.  cd packages/server');
console.log('  3.  npx ts-node src/index.ts');
console.log('  4.  curl http://localhost:3001/health');
console.log('       -> should return: {"status":"ok","version":"0.1.0"}');
console.log('');
